### Type-Guarded Function Chains

```python
from typing import Any, Callable, TypeVar

T = TypeVar('T')

def process_data(data: dict[str, Any]) -> str:
    if isinstance(data.get("type"), str) and data["type"] == "user":
        return f"Processing user {data.get('id', 'unknown')}"
    elif isinstance(data.get("type"), str) and data["type"] == "order":
        total = data.get("total", 0)
        if total > 1000:
            return f"High-value order with {len(data.get('items', []))} items"
        return "Standard order"
    else:
        return "Unknown data structure"
```
